begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(719871377184015509)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TOrbitLauncher #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<ul class="amc-TOrbitLauncher-orbit">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>'))
,p_list_template_current=>'<li class="amc-TOrbitLauncher-item is-current"><a class="amc-TOrbitLauncher-link" href="#LINK#" aria-current="page"><span class="amc-TOrbitLauncher-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TOrbitLauncher-text"><span class="amc-TOrbitLauncher-pill"><span class="amc-TOrbitLauncher-label">#TEXT#</span><span class="amc-TOrbitLauncher-caption">#A01#</span></span></span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TOrbitLauncher-item"><a class="amc-TOrbitLauncher-link" href="#LINK#"><span class="amc-TOrbitLauncher-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TOrbitLauncher-text"><span class="amc-TOrbitLauncher-pill"><span class="amc-TOrbitLauncher-label">#TEXT#</span><span class="amc-TOrbitLauncher-caption">#A01#</span></span></span></a></li>'
,p_list_template_name=>'AMC Orbit Launcher'
,p_internal_name=>'AMC_TPL_ORBIT_LAUNCHER'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-orbit-launcher.css'
,p_a01_label=>'Caption'
,p_list_template_comment=>'List template for a static or dynamic List region. The first entry becomes the hub in the center (use it for the app home or the main workspace); entries 2 to 13 orbit it, in list order, clockwise from the top. User Defined Attribute 1 is a short caption, for example ''14 pending''. The orbit pauses while the pointer is over an entry or an entry has keyboard focus; the entry grows and shows its label and caption. Keyboard order follows the list order. On touch screens labels are always visible. Containers narrower than 360px and users who prefer reduced motion get a tidy icon grid with the hub as a banner. Template options: Calm orbit, Still orbit, Always show labels, Compact, Success color.'
);
end;
